with scored as (select *, sum(amount) over (partition by customer_id order by amount, id rows between unbounded preceding and current row) as running_amount, last_value(shipping_fee) ignore nulls over (partition by customer_id order by shipping_fee, id rows between unbounded preceding and current row) as last_known_shipping_fee, avg(shipping_fee) over (order by discount, id rows between 2 preceding and 1 preceding) as shipping_fee_avg_2_prior, avg(shipping_fee) over (partition by channel, customer_id order by amount, id rows between 5 preceding and 1 preceding) as shipping_fee_avg_5_prior, cume_dist() over w_ordered as amount_cume_dist from orders window w_ordered as (partition by year(order_date) order by amount nulls first)) select date_trunc('week', order_date) as week_start, sum(amount_cume_dist) as total_amount_cume_dist, size(collect_set(channel)) as num_channels, percentile_approx(running_amount, 0.95) as running_amount_p95, avg(last_known_shipping_fee) as avg_last_known_shipping_fee from scored group by week_start having total_amount_cume_dist > 0 order by total_amount_cume_dist desc nulls last;
